			subgroup = t .. "-age-production-machine",
			ingredients = {
				{ type = "item", name = cable, amount = 4 },
				{ type = "item", name = t .. "-pump", amount = 1 },
				{ type = "item", name = "glass", amount = 2 },
				{ type = "item", name = t .. "-machine-hull", amount = 1 },
				{ type = "item", name = circuit, amount = 1 },
			},
